pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzing over caller address and amount to send
    function testFuzz_property(address caller, uint256 amount) public {
        // keep caller usable
        vm.assume(caller != address(0));
        // bound amount to a reasonable range so vm.deal works and to include 10 ether as feasible
        amount = bound(amount, 0, 100 ether);

        // fund the caller so they can send `amount`
        vm.deal(caller, amount);

        // perform the call and capture whether it succeeded (did not revert)
        bool ok;
        vm.prank(caller);
        try c.f{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract accepts the call iff msg.value == 10 ether.
        // This is the single assertion reading c's public behaviour (success of the call).
        assertTrue(ok == (amount == 10 ether));
    }
}

