pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an actor address and two timestamps (as block timestamps) and a block number
    // We'll fuzz: sender address and an initial timestamp and a later timestamp to drive the condition
    function testFuzz_property(address sender, uint256 t0, uint256 t1) public {
        // admissible domain: sender should not be zero, and amounts of ether must be 10 ether when calling
        vm.assume(sender != address(0));

        // Bound the timestamps to a realistic range to avoid overflow in vm.warp and keep them distinct
        uint256 ts0 = bound(t0, 1, 1_000_000_000); // some time in the past
        uint256 ts1 = bound(t1, 1, 1_000_000_000);

        // We want to create two scenarios: first set pastBlockTime to ts0 by warping and calling fallback
        // then attempt a second call warped to ts1. The reference requires that pastBlockTime only updates
        // when block.timestamp > pastBlockTime. Therefore, when ts1 <= ts0, reference should NOT update
        // pastBlockTime (it should remain ts0), whereas the mutant WILL update it to ts1.

        // Make sure ts0 and ts1 are within EVM allowed range and set up actor funds
        vm.deal(sender, 20 ether);

        // First call: warp to ts0 and have sender send 10 ether to trigger fallback
        vm.warp(ts0);
        vm.prank(sender);
        c.f{value: 10 ether}();

        // Ensure that pastBlockTime is at least ts0 after first call
        uint256 recorded0 = c.pastBlockTime();

        // Now second call at ts1
        vm.warp(ts1);
        vm.prank(sender);
        c.f{value: 10 ether}();

        // Single assertion: For the reference contract, if the second timestamp is <= the recorded0,
        // then pastBlockTime must NOT have changed (i.e., remain equal to recorded0). This is a universal
        // property of the reference; the mutant (which removes the check) will update pastBlockTime even when
        // ts1 <= recorded0, so the assertion will fail for some fuzz inputs where ts1 <= recorded0.
        if (ts1 <= recorded0) {
            assertTrue(c.pastBlockTime() == recorded0);
        } else {
            // If ts1 > recorded0 the reference will update pastBlockTime to ts1; still a valid universal rule
            assertTrue(c.pastBlockTime() == ts1);
        }
    }
}

