pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: actor (payer) and an initial timestamp offset to control block.timestamp
    function testFuzz_property(address payer, uint256 startTs) public {
        // keep payer as a simple EOA-like address (non-zero) and startTs in a reasonable range
        vm.assume(payer != address(0));
        startTs = bound(startTs, 1, type(uint32).max); // wide but reasonable

        // Fund the payer so it can send 10 ether
        vm.deal(payer, 20 ether);

        // 1) set block timestamp to startTs and have payer send exactly 10 ether
        vm.warp(startTs);
        vm.prank(payer);
        c.f{value: 10 ether}();

        uint256 recordedAfterFirst = c.pastBlockTime();

        // 2) Now call again without advancing time (same timestamp). On reference C, pastBlockTime should NOT change
        // because block.timestamp == pastBlockTime, so the require(block.timestamp > pastBlockTime) will fail and the call will revert.
        // We must observe that behavior via try/catch and then assert the universal property: either the second call reverts
        // (so pastBlockTime remains the same) or, if it doesn't revert, pastBlockTime must still equal recordedAfterFirst.

        // Attempt second call at same timestamp
        vm.warp(startTs);
        vm.prank(payer);
        bool ok;
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: On the correct contract, after a second payment at identical timestamp, pastBlockTime must equal recordedAfterFirst.
        // The mutant (which removes the timestamp check) can update pastBlockTime to the same timestamp (or different) and thus change it;
        // because we observed whether the call succeeded via `ok`, we assert the recorded value is unchanged.
        assertTrue(c.pastBlockTime() == recordedAfterFirst);
    }
}

