pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address payer and a timestamp (warp) value
    function testFuzz_property(address payer, uint256 warpTs) public {
        // keep payer non-zero and amount exact
        vm.assume(payer != address(0));
        uint256 amount = 10 ether;

        // fund payer so they can send
        vm.deal(payer, amount);

        // 1) set an initial pastBlockTime by calling once at timestamp T
        vm.warp(warpTs);
        vm.startPrank(payer);
        // call fallback by sending exactly 10 ether
        (bool s1, ) = address(c).call{value: amount}("");
        vm.stopPrank();
        // require the first call succeeded for the setup (if it reverts, property vacuously holds)
        // but we won't use vm.expectRevert; instead if it reverted we treat as non-updating path

        // read recorded time after first call
        uint256 recordedAfterFirst = c.pastBlockTime();

        // 2) perform a second call at the SAME timestamp warpTs
        vm.warp(warpTs); // no change in block.timestamp
        vm.deal(payer, amount);
        vm.startPrank(payer);
        (bool s2, ) = address(c).call{value: amount}("");
        vm.stopPrank();

        uint256 recordedAfterSecond = c.pastBlockTime();

        // GENERAL RULE (single assertion): If block.timestamp did not increase between two accepted payments of exactly 10 ether,
        // then the reference contract must NOT update pastBlockTime (recordedAfterSecond == recordedAfterFirst).
        // The mutant that removed the timestamp check can update pastBlockTime even when timestamps are unchanged,
        // so this assertion will fail on that mutant for some inputs.
        assertTrue(recordedAfterSecond == recordedAfterFirst);
    }
}

