pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address payer and a uint256 warpDelta (seconds to advance timestamp)
    function testFuzz_property(address payer, uint256 warpDelta) public {
        // Keep payer non-zero so vm.prank works
        vm.assume(payer != address(0));
        // bound warpDelta to a reasonable range to exercise equal and increased timestamps
        warpDelta = bound(warpDelta, 0, 5);

        // fund payer with plenty of ether
        vm.deal(payer, 100 ether);

        // 1) set an initial pastBlockTime by making one valid payment with timestamp X
        vm.warp(block.timestamp); // ensure deterministic
        vm.prank(payer);
        c.f{value: 10 ether}();
        uint256 before = c.pastBlockTime();

        // 2) optionally advance timestamp by warpDelta seconds (can be 0)
        vm.warp(block.timestamp + warpDelta);

        // 3) send another valid payment of 10 ether from the same payer
        vm.prank(payer);
        c.f{value: 10 ether}();
        uint256 after = c.pastBlockTime();

        // General property (single assertion): In the correct contract, pastBlockTime only updates when the
        // block.timestamp strictly increases; therefore after >= before and if block.timestamp did not increase
        // (warpDelta == 0) then after == before. The mutant that removed the timestamp check can make after != before
        // when warpDelta == 0. We assert the reference property: if warpDelta == 0 then pastBlockTime must be unchanged.
        if (warpDelta == 0) {
            // single assertion required by the spec
            assertTrue(after == before);
        } else {
            // when timestamp increased, the reference may update pastBlockTime to the new timestamp (or keep it if not changed by logic);
            // we still assert the monotonic non-decreasing property (after >= before)
            assertTrue(after >= before);
        }
    }
}

