pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: caller address and an arbitrary block timestamp to test behaviour
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller non-zero
        vm.assume(caller != address(0));
        // bound timestamp to a realistic range to avoid vm.warp overflow issues
        ts = bound(ts, 1, type(uint64).max);

        // Ensure caller has funds to send
        vm.deal(caller, 20 ether);

        // 1) establish an initial pastBlockTime by making a valid payment at some earlier time
        // Warp to ts - 1 to ensure initial timestamp is strictly less when possible
        uint256 initialTime = ts - 1;
        vm.warp(initialTime);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Read stored pastBlockTime after first payment
        uint256 before = c.pastBlockTime();

        // 2) Warp to the (possibly equal) target timestamp and make another payment of 10 ether
        vm.warp(ts);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Exactly one assertion: for the correct contract, pastBlockTime only updates if block.timestamp > before
        // Thus, after the second call, either block.timestamp > before and pastBlockTime == block.timestamp,
        // or block.timestamp <= before and pastBlockTime == before. We assert the OR by checking that
        // pastBlockTime is either unchanged or equals current block.timestamp.
        uint256 after = c.pastBlockTime();
        bool ok = (after == before) || (after == block.timestamp);
        assertTrue(ok);
    }
}

