    function testFuzz_property(address actor, uint256 newTimestamp) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // constrain timestamp to a reasonable future window to avoid zero/underflow weirdness
        newTimestamp = bound(newTimestamp, block.timestamp + 1, block.timestamp + 100000);

        // fund the actor so it can send 10 ether
        vm.deal(actor, 20 ether);

        // record previous pastBlockTime
        uint256 prev = c.pastBlockTime();

        // advance wall-clock time to the fuzzed timestamp to ensure block.timestamp > prev as required
        vm.warp(newTimestamp);

        // perform call as actor sending exactly 10 ether to trigger fallback
        vm.prank(actor);
        c.f{value: 10 ether}();

        // After the call, in the reference contract pastBlockTime MUST equal current block.timestamp
        // and thus be strictly greater than prev (require(block.timestamp > pastBlockTime) in code ensures call only succeeds when timestamp > prev)
        // This single assert reads the public getter of c and will hold for the correct contract for all admissible inputs,
        // while the mutant that stores block.number instead will fail for some inputs because pastBlockTime would equal a small block.number instead of the large timestamp.
        assertTrue(c.pastBlockTime() == uint256(block.timestamp));
    }
