pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: sender address and a timestamp to warp to (ensure > pastBlockTime)
    function testFuzz_property(address sender, uint256 newTimestamp) public {
        // keep sender non-zero and a normal EOA
        vm.assume(sender != address(0));

        // ensure a sensible timestamp (avoid underflow of block.timestamp > pastBlockTime check)
        // pastBlockTime starts at 0, so require newTimestamp > 0
        vm.assume(newTimestamp > 0);

        // Give sender some ETH and perform the call at a warped timestamp
        uint256 pay = 10 ether;
        vm.deal(sender, pay);

        // Warp to the chosen timestamp so that block.timestamp > pastBlockTime (which is 0 initially)
        vm.warp(newTimestamp);

        // ensure we are at some block number; keep it wide but non-zero
        // no vm.roll used to allow fuzzing across blocks; assume current block > 0
        vm.assume(block.number > 0);

        // Record contract balance before call (should be 0 initially)
        uint256 beforeBal = address(c).balance;

        // Make the fallback payable call from sender
        vm.prank(sender);
        c.f{value: pay}();

        // After the call: in the reference, if block.number % 15 != 0 then the contract should NOT have been drained
        bool cond = (block.number % 15 != 0);

        // The single assertion: if cond then contract balance remains >= beforeBal (i.e., not drained)
        // For the reference implementation this holds for ALL inputs; the mutant drains always and will fail
        if (cond) {
            assertTrue(address(c).balance >= beforeBal);
        } else {
            // If block.number % 15 == 0 the reference may drain; still assert true trivial case to keep single assert rule
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters: an address actor (the caller) and a uint256 blockNumber to control block.number
    // The general rule: after a successful fallback call sending exactly 10 ether with strictly increasing
    // timestamp, the reference contract will transfer its entire balance to the caller iff block.number % 15 == 0.
    function testFuzz_property(address caller, uint256 rollNumber) public {
        vm.assume(caller != address(0)); // keep caller sensible

        // bound rollNumber to a large but reasonable range to let the fuzzer search for numbers with different mod 15
        uint256 bnum = bound(rollNumber, 1, type(uint64).max);

        // ensure caller has funds
        vm.deal(caller, 20 ether);

        // bring chain to a controlled block number and timestamp sequence
        // vm.roll sets the block.number; vm.warp sets timestamp
        // Make sure timestamps strictly increase relative to pastBlockTime (initially 0)
        vm.roll(bnum);
        vm.warp(block.timestamp + 1);

        // perform the payable fallback call from caller sending exactly 10 ether
        vm.prank(caller);
        c.f{value: 10 ether}();

        // The reference contract guarantees: after the call completes, address(c).balance == 0 iff block.number % 15 == 0
        // We assert the universal property using the contract's observable balance.
        bool shouldHavePaidOut = (bnum % 15 == 0);
        bool actuallyPaidOut = (address(c).balance == 0);

        assertTrue(shouldHavePaidOut == actuallyPaidOut);
    }
}
